import { View, Text, StyleSheet } from "react-native";
import { useMemo } from "react";
import { registerRootComponent } from "expo";

const CART = [
  { id: "1", name: "Чихэвч", price: 159000 },
  { id: "2", name: "Гар цаг", price: 249000 },
  { id: "3", name: "Цүнх", price: 129000 },
];

function App() {
  const total = useMemo(() => CART.reduce((sum, p) => sum + p.price, 0), []);
  return (
    <View style={styles.s}>
      <Text style={styles.h}>Сагс</Text>
      <Text nativeID="total" style={styles.total}>Нийт: {total}₮</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 24, gap: 10, justifyContent: "center" },
  h: { fontSize: 20, fontWeight: "bold" },
  total: { fontSize: 22, fontWeight: "bold", color: "#2563eb" },
});

registerRootComponent(App);
